drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · a generic page of results★★☆ core
//  concepts: generic methods · validation · paging arithmetic
// ─────────────────────────────────────────────────────────────────────────
//
//  One helper for every list endpoint.

using static Bootcamp.Check;

Page<T> Paginate<T>(IReadOnlyList<T> items, int page, int size)
{
    if (page < 1) throw new ArgumentOutOfRangeException(nameof(page));
    if (size is < 1 or > 100) throw new ArgumentOutOfRangeException(nameof(size));
    var totalPages = (items.Count + size - 1) / size;
    var slice = items.Skip((page - 1) * size).Take(size).ToList();
    return new Page<T>(slice, page, totalPages, page < totalPages);
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("the last partial page", () =>
{
    var p = Paginate(Enumerable.Range(1, 25).ToList(), 3, 10);
    Eq(p.Items, new[] { 21, 22, 23, 24, 25 });
    Eq(p.TotalPages, 3);
    Eq(p.HasNext, false);
});

Test("a middle page has a next page", () =>
{
    var p = Paginate(Enumerable.Range(1, 25).ToList(), 2, 10);
    Eq(p.Items.First(), 11);
    Eq(p.HasNext, true);
});

Test("works for any element type", () =>
{
    var p = Paginate(new List<string> { "a", "b", "c" }, 1, 2);
    Eq(p.Items, new[] { "a", "b" });
    Eq(p.TotalPages, 2);
});

Test("no items: zero pages and an empty page (boundary)", () =>
{
    var p = Paginate(new List<int>(), 1, 10);
    Eq(p.Items.Count, 0);
    Eq(p.TotalPages, 0);
    Eq(p.HasNext, false);
});

Test("a page past the end is empty", () =>
    Eq(Paginate(Enumerable.Range(1, 5).ToList(), 9, 10).Items.Count, 0));

Test("bad page or size throws ArgumentOutOfRangeException", () =>
{
    Throws<ArgumentOutOfRangeException>(() => Paginate(new List<int>(), 0, 10));
    Throws<ArgumentOutOfRangeException>(() => Paginate(new List<int>(), 1, 0));
    Throws<ArgumentOutOfRangeException>(() => Paginate(new List<int>(), 1, 101));
});

drills.explanation:
Validate first, then compute the page count with ceiling division and slice with Skip/Take:

```csharp
var totalPages = (items.Count + size - 1) / size;
var slice = items.Skip((page - 1) * size).Take(size).ToList();
return new Page<T>(slice, page, totalPages, page < totalPages);
```

A plain `items.Count / size` rounds down: 25 items at 10 per page give 2 pages, and the test "the last partial page" fails on `TotalPages`. `Take(size)` stops at the end of the list, so a partial or past-the-end page holds only real items, never `default(T)` fillers. `ToList()` materialises the page, so the result does not re-run the query (topic 09). The method never names a concrete element type, which is why the same code serves ints and strings.

